from sqlalchemy.ext.asyncio import AsyncSessionfrom base.service import BaseServicefrom container.model import Container, ContainerTypefrom container.repository import ContainerRepositoryfrom helpers.search import Paginationfrom container.schemas import FullContainerShowclass ContainerService(BaseService[Container, ContainerRepository]):    def __init__(self, session: AsyncSession, type: ContainerType | None = None):        super().__init__(Container, session, ContainerRepository)        self.type = type    async def create_container(self, **fields):        return await self.create_item(type=self.type, **fields)    async def get_container(self, **filters):        return await self.get_item_by(type=self.type, **filters)    async def search_containers(self, **filters):        return await self.search_items(type=self.type, **filters)    async def get_full_containers(            self, pagination: Pagination,    ) -> list[FullContainerShow]:        result = await self.repository.get_containers_with_content_counts(**pagination.dict())        return [            FullContainerShow(                container=container,                post_count=post_count,                comment_count=comment_count            )            for container, post_count, comment_count in result        ]    async def get_full_container(self, container: Container) -> FullContainerShow:        container, post_count, comment_count = \            await self.repository.get_containers_with_content_counts(container_id=container.id)        return FullContainerShow(container=container, post_count=post_count, comment_count=comment_count)